<div class="page-title clearfix"><h1>Almacenes</h1><?php if($can_manage)echo modal_anchor(get_uri('warehouses/form'),'<i data-feather="plus" class="icon-16"></i> Nuevo almacén',['class'=>'btn btn-primary float-end','title'=>'Nuevo almacén']); ?></div><div class="card"><div class="table-responsive"><table id="warehouses-table" class="display" width="100%"></table></div></div><script>$(function(){var t=$('#warehouses-table').appTable({source:'<?php echo get_uri('warehouses/catalog/list'); ?>',columns:[{title:'Código'},{title:'Almacén'},{title:'Responsable'},{title:'Teléfono'},{title:'Estado'},{title:'Acciones',class:'text-center option w100'}]});$(document).on('click','.warehouse-toggle',function(){var id=$(this).data('id');$.post('<?php echo get_uri('warehouses/toggle'); ?>',{id:id,'<?php echo csrf_token(); ?>':'<?php echo csrf_hash(); ?>'},function(r){appAlert.success(r.message);t.appTable({reload:true});},'json');});});</script>
